#include <iostream>
#include <string>
#include <iomanip>

class PhoneNumber {
    friend std::ostream &operator<<(std::ostream &out, const PhoneNumber &p);
    friend std::istream &operator>>(std::istream &in, PhoneNumber &p);
private:
    std::string areaCode;
    std::string exchange;
    std::string line;
};

std::ostream &operator<<(std::ostream &out, const PhoneNumber &p) {
    out << "(" << p.areaCode << ") " << p.exchange << "-" << p.line;
    return out;
}

std::istream &operator>>(std::istream &in, PhoneNumber &p) {
    in.ignore(); // skip '('
    in >> std::setw(3) >> p.areaCode;
    in.ignore(2); // skip ") "
    in >> std::setw(3) >> p.exchange;
    in.ignore(); // skip '-'
    in >> std::setw(4) >> p.line;
    return in;
}

int main() {
    PhoneNumber phone;
    if (std::cin >> phone) {
        std::cout << "Phone: " << phone << "\n";
    }
    return 0;
}

body.vi:
Một toán tử một ngôi (unary operator) có thể được nạp chồng dưới dạng một hàm thành viên không static (non-static member function) không nhận đối số nào. Hàm bắt buộc phải là non-static để có thể truy cập dữ liệu thành viên của đối tượng hiện tại thông qua con trỏ ẩn `this`.

Ví dụ, khi kiểm tra xem một đối tượng chuỗi `s` có rỗng hay không bằng biểu thức `!s`, trình biên dịch sẽ chuyển đổi biểu thức này thành lời gọi hàm thành viên `s.operator!()`. Nếu toán tử không sửa đổi trạng thái của đối tượng, hàm nên được đánh dấu là phương thức hằng (`const`):

```cpp
class String {
public:
    bool operator!() const; // gọi qua !s -> s.operator!()
};
```

body.en:
A unary operator can be overloaded as a non-static member function taking no arguments. The function must be non-static so that it can access the invoking instance's non-static data members via the implicit `this` pointer.

For example, testing if an object `s` of a custom string class is empty using `!s` causes the compiler to generate the call `s.operator!()`. If the operator does not alter the object's state, it should be declared as a `const` member function:

```cpp
class String {
public:
    bool operator!() const; // invoked as !s -> s.operator!()
};
```

