#include <iostream>
#include <string>

class CustomBuffer {
private:
    std::string data;
public:
    explicit CustomBuffer(std::string str = "") : data(std::move(str)) {}

    // Unary operator! overloaded as a const member function
    bool operator!() const {
        return data.empty();
    }

    const std::string &getData() const { return data; }
};

int main() {
    CustomBuffer emptyBuf;
    CustomBuffer filledBuf("Modern C++");

    std::cout << std::boolalpha;
    std::cout << "emptyBuf is empty: " << (!emptyBuf) << "\n";
    std::cout << "filledBuf is empty: " << (!filledBuf) << "\n";

    return 0;
}
